def get_js_bytes() -> bytes:
    """Return the original JS bundle bytes."""
    raw = gzip.decompress(base64.b64decode(_JS_GZIP_BASE64))
    got = hashlib.sha256(raw).hexdigest()
    if got != ORIGINAL_SHA256:
        raise RuntimeError(f"Embedded JS checksum mismatch: {got} != {ORIGINAL_SHA256}")
    return raw


def get_js_text(encoding: str = "utf-8") -> str:
    """Return the JS bundle decoded as text. Invalid bytes are replaced."""
    return get_js_bytes().decode(encoding, errors="replace")


def extract_js(output_path: str | os.PathLike[str] = "restored_123123.js") -> Path:
    """Write the embedded JS bundle back to disk exactly."""
    out = Path(output_path)
    out.write_bytes(get_js_bytes())
    return out


_NODE_RUNNER = '\nglobal.self = global;\nif (typeof global.window === \'undefined\') global.window = undefined;\n\nconst fs = require(\'fs\');\nconst path = require(\'path\');\n\nconst bundlePath = process.argv[1];\nconst inputPath = process.argv[2] || \'\';\nconst outputPath = process.argv[3] || \'\';\nconst mode = process.argv[4] || \'decrypt\';\n\nconst mod = require(bundlePath);\n\nasync function main() {\n  if (mode === \'check\') {\n    console.log(JSON.stringify({ ok: true, exports: Object.keys(mod) }));\n    return;\n  }\n\n  if (!inputPath) {\n    throw new Error(\'Missing input file path.\');\n  }\n\n  const Decrypt = mod.Decrypt || mod.default || mod;\n  if (typeof Decrypt !== \'function\') {\n    throw new Error(\'The JS bundle does not expose a callable Decrypt function.\');\n  }\n\n  const buf = fs.readFileSync(inputPath);\n  const name = path.basename(inputPath);\n  const file = typeof File !== \'undefined\'\n    ? new File([buf], name)\n    : Object.assign(new Blob([buf]), { name });\n\n  const result = await Decrypt(file);\n  const blob = result.blob || result.file || result;\n  if (!blob || typeof blob.arrayBuffer !== \'function\') {\n    throw new Error(\'Decrypt did not return a Blob-like result.\');\n  }\n\n  const data = Buffer.from(await blob.arrayBuffer());\n  const safeTitle = String(result.title || path.parse(inputPath).name)\n    .replace(/[\\\\/:*?"<>|\\r\\n]+/g, \'_\')\n    .trim() || path.parse(inputPath).name;\n  const ext = String(result.ext || path.extname(inputPath).replace(/^\\./, \'\') || \'bin\').replace(/^\\./, \'\');\n  const out = outputPath || path.join(path.dirname(inputPath), safeTitle + \'.\' + ext);\n  fs.writeFileSync(out, data);\n\n  console.log(JSON.stringify({\n    ok: true,\n    output: out,\n    title: result.title || \'\',\n    artist: result.artist || \'\',\n    album: result.album || \'\',\n    ext: result.ext || \'\',\n    mime: result.mime || \'\',\n    bytes: data.length\n  }));\n}\n\nmain().catch((err) => {\n  console.error(JSON.stringify({ ok: false, error: String(err && err.stack || err) }));\n  process.exit(1);\n});\n'


def _run_node(bundle_path: Path, input_path: str | None = None, output_path: str | None = None, *, check: bool = False) -> dict:
    args = ["node", "-e", _NODE_RUNNER, str(bundle_path), input_path or "", output_path or "", "check" if check else "decrypt"]
    try:
        completed = subprocess.run(args, check=False, capture_output=True, text=True)
    except FileNotFoundError as exc:
        raise RuntimeError("Node.js is required to execute this bundled JS. Please install Node.js and ensure `node` is in PATH.") from exc

    stream = completed.stdout.strip() or completed.stderr.strip()
    try:
        data = json.loads(stream.splitlines()[-1]) if stream else {}
    except Exception:
        data = {"ok": False, "raw_output": stream}

    if completed.returncode != 0 or not data.get("ok"):
        raise RuntimeError(data.get("error") or data.get("raw_output") or f"Node exited with code {completed.returncode}")
    return data


def check_node() -> dict:
    """Verify that Node.js can load the embedded JS bundle."""
    with tempfile.TemporaryDirectory(prefix="decrypt_js_") as td:
        bundle = Path(td) / ORIGINAL_NAME
        bundle.write_bytes(get_js_bytes())
        return _run_node(bundle, check=True)


def decrypt_file(input_path: str | os.PathLike[str], output_path: str | os.PathLike[str] | None = None) -> dict:
    """Decrypt one supported music file by delegating to the embedded JS bundle through Node.js."""
    input_path = str(input_path)
    output_arg = str(output_path) if output_path else None
    with tempfile.TemporaryDirectory(prefix="decrypt_js_") as td:
        bundle = Path(td) / ORIGINAL_NAME
        bundle.write_bytes(get_js_bytes())
        return _run_node(bundle, input_path, output_arg)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Embedded Python wrapper for 123123.js decrypt bundle.")
    parser.add_argument("input", nargs="?", help="Input encrypted/audio file, e.g. .ncm/.qmc/.kwm/.xm")
    parser.add_argument("-o", "--output", help="Output path. If omitted, a name is generated from metadata.")
    parser.add_argument("--extract-js", metavar="PATH", help="Restore the embedded JS bundle to this path and exit.")
    parser.add_argument("--check", action="store_true", help="Check whether Node.js can load the embedded JS bundle.")
    args = parser.parse_args(argv)

    if args.extract_js:
        out = extract_js(args.extract_js)
        print(json.dumps({"ok": True, "js_path": str(out), "sha256": ORIGINAL_SHA256}, ensure_ascii=False))
        return 0

    if args.check:
        print(json.dumps(check_node(), ensure_ascii=False))
        return 0

    if not args.input:
        parser.print_help()
        return 2

    print(json.dumps(decrypt_file(args.input, args.output), ensure_ascii=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
